window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fdae0f71934f9b8a"]={"versions": [{"id": "FIG-fdae0f71934f9b8a", "releases": ["R21-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsdiagramm (State Machine Diagram) zur Definition des formalen Laufzeitmodells.</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li><strong>Modul:</strong> ARTI (<em>AUTOSAR Run-Time Interface</em>, Classic Platform R21-11 / R24-11).</li>\n<li><strong>Zweck:</strong> Standardisierung des formalen Zustandsmodells für Kategorie-1-Interrupt-Service-Routinen (<code>CAT1 ISR</code>) zur Erfassung durch externe Timing-, Trace- und Debug-Werkzeuge (z. B. Profiling, Laufzeit- und Latenzanalysen).</li>\n<li><strong>Einordnung:</strong> CAT1-ISRs umgehen den AUTOSAR-OS-Kontext und werden direkt über den Hardware-Interrupt-Vektor bedient (ohne OS-Scheduling-Overhead). Das Zustandsmodell abstrahiert daher alle OS-verwalteten Zwischenzustände (wie <code>Ready</code>, <code>Waiting</code> oder <code>Suspended</code>) auf eine rein binäre Ausführungslogik.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände (States):</strong></li>\n<li><strong><code>Inactive</code>:</strong> Die Interrupt-Service-Routine ist passiv, d. h. es findet keine Befehlsausführung dieser ISR auf dem Core statt.</li>\n<li><strong><code>Running</code>:</strong> Die CAT1-ISR befindet sich in aktiver Ausführung auf der zugewiesenen CPU/Core.</li>\n<li><strong>Transitionen & Events:</strong></li>\n<li><strong><code>Start</code>:</strong> Zustandswechsel von <code>Inactive</code> nach <code>Running</code>. Korrespondiert semantisch mit dem Eintrittszeitpunkt in die ISR-Routine (Hook/Trace-Point).</li>\n<li><strong><code>Stop</code>:</strong> Zustandswechsel von <code>Running</code> nach <code>Inactive</code>. Korrespondiert mit dem Austrittszeitpunkt unmittelbar vor Rücksprung aus dem Interrupt-Kontext (<code>RETI</code>/<code>ERET</code>).</li>\n<li><strong>Metamodell-Bezug:</strong></li>\n<li>Bindung an das ARTI-Metamodell-Element <code>ArtiCat1Isr</code>.</li>\n<li>Da CAT1-ISRs nicht über OS-Task-/Resource-Deskriptoren verwaltet werden, existieren keine OS-Synchronisations- oder Sperrmechanismen (keine OS-Spinlocks, Events oder Ressourcen-Bindungen im Modell).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Ruhezustand:</strong> Die ISR verweilt im Zustand <code>Inactive</code>.</li>\n<li><strong>Interrupt-Eintritt (<code>Start</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Hardware-Interrupt triggert den Vektorsprung.</li>\n<li>Im Prolog der CAT1-ISR feuert der ARTI-Trace-Hook (z. B. Write auf Instrumentierungsadresse oder Software-Breakpoint/Trace-Marker).</li>\n<li>Die Transition nach <code>Running</code> wird signalisiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ausführungsphase (<code>Running</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abarbeitung des applikativen bzw. treiberspezifischen ISR-Payloads im Interrupt-Kontext.</li>\n<li>Präemption durch höher priorisierte Interrupts (Nested ISRs) unterbricht die physische Ausführung, verändert im ARTI-Zustandsmodell der unterbrochenen ISR jedoch nicht zwingend deren Status <code>Running</code> (die Rekonstruktion der aktiven Core-Belegung obliegt dem Trace-Tool über den Core-Kontext).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Interrupt-Austritt (<code>Stop</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Unmittelbar vor Abschluss des ISR-Epilogs feuert der korrespondierende ARTI-Exit-Hook.</li>\n<li>Transition zurück in den Zustand <code>Inactive</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Instrumentierung & Overhead (Treiber/MCAL/BSW):</strong></li>\n<li>Da CAT1-ISRs für extrem latenzkritische Pfade gewählt werden, müssen die ARTI-Trace-Punkte (<code>Start</code>, <code>Stop</code>) manuell oder via Codegenerator minimal-invasiv implementiert werden (bevorzugt Single-Cycle Memory/DWT-Writes statt funktionaler Callbacks).</li>\n<li><strong>API-Einschränkungen:</strong></li>\n<li>Im Zustand <code>Running</code> dürfen keinerlei AUTOSAR-OS-APIs aufgerufen werden, die eine Kontextumschaltung oder OS-Fehlerbehandlung erfordern (striktes CAT1-Paradigma).</li>\n<li><strong>Trace- & Tool-Konfiguration:</strong></li>\n<li>ARTI-Generatoren exportieren die Hooks in die ARTI-Beschreibungsdatei (<code>.arxml</code>), um Rekonstruktions-Tools mit den physikalischen Adressen/IDs der <code>Start</code>- und <code>Stop</code>-Events zu synchronisieren.</li>\n<li>Fehlt die Instrumentierung an einem der beiden Übergänge, resultiert dies in inkonsistenten Tool-Metriken (Dauerlauf-Fehldetektion oder fehlende Aktivierungszählung).</li>\n</ul>"}, {"id": "FIG-79db1f2e03f8ee0e", "releases": ["R22-11", "R23-11", "R25-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsdiagramm (State Machine Diagram) zur Definition des formalen Laufzeitmodells.</li>\n<li><strong>Architektur-Kontext:</strong></li>\n<li><strong>Modul:</strong> ARTI (<em>AUTOSAR Run-Time Interface</em>, Classic Platform R21-11 / R24-11).</li>\n<li><strong>Zweck:</strong> Standardisierung des formalen Zustandsmodells für Kategorie-1-Interrupt-Service-Routinen (<code>CAT1 ISR</code>) zur Erfassung durch externe Timing-, Trace- und Debug-Werkzeuge (z. B. Profiling, Laufzeit- und Latenzanalysen).</li>\n<li><strong>Einordnung:</strong> CAT1-ISRs umgehen den AUTOSAR-OS-Kontext und werden direkt über den Hardware-Interrupt-Vektor bedient (ohne OS-Scheduling-Overhead). Das Zustandsmodell abstrahiert daher alle OS-verwalteten Zwischenzustände (wie <code>Ready</code>, <code>Waiting</code> oder <code>Suspended</code>) auf eine rein binäre Ausführungslogik.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustände (States):</strong></li>\n<li><strong><code>Inactive</code>:</strong> Die Interrupt-Service-Routine ist passiv, d. h. es findet keine Befehlsausführung dieser ISR auf dem Core statt.</li>\n<li><strong><code>Running</code>:</strong> Die CAT1-ISR befindet sich in aktiver Ausführung auf der zugewiesenen CPU/Core.</li>\n<li><strong>Transitionen & Events:</strong></li>\n<li><strong><code>Start</code>:</strong> Zustandswechsel von <code>Inactive</code> nach <code>Running</code>. Korrespondiert semantisch mit dem Eintrittszeitpunkt in die ISR-Routine (Hook/Trace-Point).</li>\n<li><strong><code>Stop</code>:</strong> Zustandswechsel von <code>Running</code> nach <code>Inactive</code>. Korrespondiert mit dem Austrittszeitpunkt unmittelbar vor Rücksprung aus dem Interrupt-Kontext (<code>RETI</code>/<code>ERET</code>).</li>\n<li><strong>Metamodell-Bezug:</strong></li>\n<li>Bindung an das ARTI-Metamodell-Element <code>ArtiCat1Isr</code>.</li>\n<li>Da CAT1-ISRs nicht über OS-Task-/Resource-Deskriptoren verwaltet werden, existieren keine OS-Synchronisations- oder Sperrmechanismen (keine OS-Spinlocks, Events oder Ressourcen-Bindungen im Modell).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Ruhezustand:</strong> Die ISR verweilt im Zustand <code>Inactive</code>.</li>\n<li><strong>Interrupt-Eintritt (<code>Start</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Hardware-Interrupt triggert den Vektorsprung.</li>\n<li>Im Prolog der CAT1-ISR feuert der ARTI-Trace-Hook (z. B. Write auf Instrumentierungsadresse oder Software-Breakpoint/Trace-Marker).</li>\n<li>Die Transition nach <code>Running</code> wird signalisiert.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ausführungsphase (<code>Running</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Abarbeitung des applikativen bzw. treiberspezifischen ISR-Payloads im Interrupt-Kontext.</li>\n<li>Präemption durch höher priorisierte Interrupts (Nested ISRs) unterbricht die physische Ausführung, verändert im ARTI-Zustandsmodell der unterbrochenen ISR jedoch nicht zwingend deren Status <code>Running</code> (die Rekonstruktion der aktiven Core-Belegung obliegt dem Trace-Tool über den Core-Kontext).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Interrupt-Austritt (<code>Stop</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Unmittelbar vor Abschluss des ISR-Epilogs feuert der korrespondierende ARTI-Exit-Hook.</li>\n<li>Transition zurück in den Zustand <code>Inactive</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Instrumentierung & Overhead (Treiber/MCAL/BSW):</strong></li>\n<li>Da CAT1-ISRs für extrem latenzkritische Pfade gewählt werden, müssen die ARTI-Trace-Punkte (<code>Start</code>, <code>Stop</code>) manuell oder via Codegenerator minimal-invasiv implementiert werden (bevorzugt Single-Cycle Memory/DWT-Writes statt funktionaler Callbacks).</li>\n<li><strong>API-Einschränkungen:</strong></li>\n<li>Im Zustand <code>Running</code> dürfen keinerlei AUTOSAR-OS-APIs aufgerufen werden, die eine Kontextumschaltung oder OS-Fehlerbehandlung erfordern (striktes CAT1-Paradigma).</li>\n<li><strong>Trace- & Tool-Konfiguration:</strong></li>\n<li>ARTI-Generatoren exportieren die Hooks in die ARTI-Beschreibungsdatei (<code>.arxml</code>), um Rekonstruktions-Tools mit den physikalischen Adressen/IDs der <code>Start</code>- und <code>Stop</code>-Events zu synchronisieren.</li>\n<li>Fehlt die Instrumentierung an einem der beiden Übergänge, resultiert dies in inkonsistenten Tool-Metriken (Dauerlauf-Fehldetektion oder fehlende Aktivierungszählung).</li>\n</ul>"}], "trans": [{"from": "FIG-fdae0f71934f9b8a", "to": "FIG-79db1f2e03f8ee0e", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-79db1f2e03f8ee0e", "to": "FIG-fdae0f71934f9b8a", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
